    counts = [{} for x in sites]
    totals = [0.0] * len(sites)
    for edge in edges:
        i = edge.get('i')
        d = edge.get('distance_A')
        if i is not None and 0 <= i < len(sites) and d is not None and d > 0:
            nearest[i] = min(nearest[i], d)
    for edge in edges:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A')
        if i is None or j is None or d is None or d <= 0:
            continue
        if 0 <= i < len(sites) and 0 <= j < len(sites) and d <= 1.25 * nearest[i]:
            element = sites[j].get('element')
            if element is None:
                continue
            o = sites[j].get('occupancy')
            w = max(0.0, o if o is not None else 1.0)
            counts[i][element] = counts[i].get(element, 0.0) + w
            totals[i] += w
    entropy = 0.0
    number = 0
    for i in range(len(sites)):
        if totals[i] > 0:
            for count in counts[i].values():
                if count > 0:
                    p = count / totals[i]
                    entropy -= p * log(p)
            number += 1
    return entropy / number if number else 0.0

