    sites = s.get('sites') or []
    matrix = (s.get('lattice') or {}).get('matrix')
    if matrix is None or len(matrix) != 3:
        return 0.0
    if any(row is None or len(row) != 3 for row in matrix):
        return 0.0
    edges = s.get('neighbors') or []
    nearest = [inf] * len(sites)
    vectors = [[0.0, 0.0, 0.0] for site in sites]
    counts = [0] * len(sites)
    for edge in edges:
        i = edge.get('i')
        d = edge.get('distance_A')
        if i is not None and 0 <= i < len(sites) and d is not None and d > 0:
            nearest[i] = min(nearest[i], d)
    for edge in edges:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A')
        if i is None or j is None or d is None or d <= 0:
            continue
        if not (0 <= i < len(sites) and 0 <= j < len(sites)):
            continue
        if d > 1.25 * nearest[i]:
            continue
        a = sites[i].get('frac_coords')
        b = sites[j].get('frac_coords')
        image = edge.get('image')
        if a is None or b is None or image is None:
            continue
        if len(a) != 3 or len(b) != 3 or len(image) != 3:
            continue
        f = [b[k] + image[k] - a[k] for k in range(3)]
        v = [sum(f[k] * matrix[k][t] for k in range(3)) for t in range(3)]
        norm = sqrt(sum(x * x for x in v))
        if norm > 0:
            for t in range(3):
                vectors[i][t] += v[t] / norm
            counts[i] += 1
    values = [sqrt(sum(x * x for x in vectors[i])) / counts[i] for i in range(len(sites)) if counts[i] > 0]
    return sum(values) / len(values) if values else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    matrix = (s.get('lattice') or {}).get('matrix')
    if matrix is None or len(matrix) != 3:
        return 0.0
    if any(row is None or len(row) != 3 for row in matrix):
        return 0.0
    bonds = [[] for site in sites]
    for edge in s.get('neighbors') or []:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A')
        if i is None or j is None or d is None or d <= 0:
            continue
        if not (0 <= i < len(sites) and 0 <= j < len(sites)):
            continue
        if len(bonds[i]) == 4 and d > bonds[i][3][0]:
            continue
        a = sites[i].get('frac_coords')
        b = sites[j].get('frac_coords')
        image = edge.get('image')
        if a is None or b is None or image is None:
            continue
        if len(a) != 3 or len(b) != 3 or len(image) != 3:
            continue
        f = [b[k] + image[k] - a[k] for k in range(3)]
        v = [sum(f[k] * matrix[k][t] for k in range(3)) for t in range(3)]
        norm = sqrt(sum(x * x for x in v))
        if norm > 0:
            bond = (d, v[0] / norm, v[1] / norm, v[2] / norm)
            bonds[i] = sorted(bonds[i] + [bond])[:4]
    total = 0.0
    number = 0
    for local in bonds:
        if len(local) == 4:
            penalty = 0.0
            for a in range(4):
                for b in range(a + 1, 4):
                    dot = sum(local[a][k] * local[b][k] for k in range(1, 4))
                    penalty += (max(-1.0, min(1.0, dot)) + 1.0 / 3.0) ** 2
            total += 1.0 - 0.375 * penalty
            number += 1
    return total / number if number else 0.0

